import{z as n,x as s,o as B,c as p,q as l,j as o,D as t,d as e,s as A,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"数据加载与预处理流水线","description":"","frontmatter":{"title":"数据加载与预处理流水线","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ti-data-pipeline.md","filePath":"llm/ti-data-pipeline.md","lastUpdated":1791063341000}'),d={name:"llm/ti-data-pipeline.md"};function D(m,E,C,h,F,f){const r=s("Mermaid");return B(),p("div",null,[E[2]||(E[2]=l('<h1 id="数据加载与预处理流水线" tabindex="-1">数据加载与预处理流水线 <a class="header-anchor" href="#数据加载与预处理流水线" aria-label="Permalink to &quot;数据加载与预处理流水线&quot;">​</a></h1><div class="epigraph"><p>数据侧的工程目标只有一句话：让队列在 P99 之下非空，并且任何时刻都能说出「下一批是什么、凭什么」。</p><footer>—— 据 WebDataset、Mosaic Streaming 等流式加载实践与 BLOOM 训练纪事整理</footer></div><p><a href="/llm/ti-training-loop-anatomy">上一课</a>把步时拆成计算、通信、等数据三桶，钩子与状态都钉在 step 骨架上。「等数据」那桶不会自己消失：取批阶段底下是一条跨磁盘、网络、CPU 与 GPU 的流水线。流水的阶段划分——分片、抽权、过滤、分词、打包、预取——<a href="/llm/dataloader-pipeline">数据加载流水线</a>已经写过，存储介质的取舍在<a href="/llm/dataset-storage-streaming">数据集存储与流式加载</a>。本课写的是把它当生产设施来运营：吞吐有账、确定性有契约、故障有隔离、变更有版本。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>流水线的失败模式很少是「读不到文件」，而是三类更隐蔽的错位。其一，<strong>吞吐错位</strong>：均值够、P99 不够，某个冷分片或慢 worker 让队列周期性见底，GPU 每步插一小段空转，混进「等数据」桶却常被误记成通信。其二，<strong>一致性错位</strong>：预分词正则或特殊 token 用了与训练快照不同的版本，<a href="/llm/pretokenization-regex">预分词正则</a>一变，fertility 报表与实际 token 流对不上，配比账全错。其三，<strong>可复现错位</strong>：出了坏批想回放，却发现洗牌种子、分片顺序、过滤版本没有一项被钉住，坏批永远无法重现。</p><p><span class="marginnote">术语翻译：P99 就是把一段时间内所有耗时从小到大排队，取第 99% 位置的那个值——它回答「最倒霉的那 1% 有多慢」。均值会被大量快请求掩盖少数慢请求，而训练每一步都要等齐最慢的那份数据才敢往下走，所以流水线的健康度要看分位数，不是均值。</span></p><h3 id="把流水线当设施运营的三份账" tabindex="-1">把流水线当设施运营的三份账 <a class="header-anchor" href="#把流水线当设施运营的三份账" aria-label="Permalink to &quot;把流水线当设施运营的三份账&quot;">​</a></h3><p>吞吐账：每主机记录队列水位、各阶段耗时的分位数与每秒产出的 token 数，报警条件是「队列低于阈值持续若干步」而不是 CPU 利用率。确定性账：全局游标、shuffle 种子、过滤与打包的版本共同构成<strong>数据指纹</strong>，与上一课的「不改变轨迹」契约对接——resume 与坏批回放都靠它。变更账：tokenizer 快照、正则、过滤规则、配比权重任何一项变更都要升流水线版本号，旧版本必须仍可重建。</p><p><span class="marginnote">回放坏批的最小配置是四元组：流水线版本号、shuffle 种子与 epoch、全局游标位置、worker 数。缺一项，事故复盘就只能靠猜；这四项应当随每个微批的日志一起落盘。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>运营动作按三账落。吞吐账上，先测单 worker 的阶段耗时剖面，找出瓶颈在解压、正则还是分词；<a href="/llm/tokenizer-parallel">分词并行</a>决定 CPU 侧怎么扩，预取槽深按 P99 解压延迟而不是均值设定，并以队列水位做背压。确定性账上，洗牌用「种子 + epoch」的确定性算法，游标存「分片 id + 偏移」，坏批回放时固定 worker 数重跑该区间——这也是流水线的 CI 用例：每次改动后，用黄金区间重放，比对 token 序列哈希，不一致即失败。变更账上，配比调整走<a href="/llm/data-mixture-laws">数据配比</a>的实验口径，但<strong>分发</strong>走版本号：正在跑的作业永远绑定创建时的版本，新版本只对新作业生效。</p>',11)),(B(),o(i,null,{default:t(()=>[A(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SH%5B%22%E5%88%86%E7%89%87%E6%B8%85%E5%8D%95%20%2B%20%E9%85%8D%E6%AF%94%E6%9D%83%E9%87%8D%20v%22%5D%20--%3E%20RD%5B%22%E6%8C%89%E5%BA%8F%E8%AF%BB%E5%8F%96%2C%20%E8%AE%B0%E5%BD%95%E6%B8%B8%E6%A0%87%22%5D%0A%20%20RD%20--%3E%20FL%5B%22%E8%BF%87%E6%BB%A4%E4%B8%8E%E6%8C%87%E7%BA%B9%E5%8E%BB%E9%87%8D%22%5D%0A%20%20FL%20--%3E%20TK%5B%22%E5%88%86%E8%AF%8D%3A%20tokenizer%20%E5%BF%AB%E7%85%A7%20v%22%5D%0A%20%20TK%20--%3E%20PK%5B%22%E6%89%93%E5%8C%85%E4%B8%8E%E9%95%BF%E5%BA%A6%E5%88%86%E6%A1%B6%22%5D%0A%20%20PK%20--%3E%20BUF%5B%22%E6%9C%89%E7%95%8C%E9%98%9F%E5%88%97%3A%20%E8%83%8C%E5%8E%8B%22%5D%0A%20%20BUF%20--%3E%20GPU%5B%22%E8%AE%AD%E7%BB%83%E5%BE%AA%E7%8E%AF%E5%8F%96%E6%89%B9%22%5D%0A%20%20MON%5B%22%E7%9B%91%E6%8E%A7%3A%20%E6%B0%B4%E4%BD%8D%20%2F%20%E5%90%84%E9%98%B6%E6%AE%B5%20P99%20%2F%20token%20%E9%80%9F%E7%8E%87%22%5D%20--%3E%20AL%7B%22%E6%B0%B4%E4%BD%8D%E5%91%8A%E8%AD%A6%3F%22%7D%0A%20%20AL%20--%3E%7C%E6%98%AF%7C%20DIG%5B%22%E6%8C%89%E9%98%B6%E6%AE%B5%E5%89%96%E9%9D%A2%E6%89%BE%E7%93%B6%E9%A2%88%22%5D%0A%20%20AL%20--%3E%7C%E5%90%A6%7C%20SH%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[e("三份账为什么缺一不可：流水线是分布在一批主机上的有状态系统，没有吞吐账，退化是渐进的——每步多等 5 毫秒，在日志里只是吞吐从 42 掉到 40，直到有人对账才发现已损失一成算力。没有确定性账， resume 回到的是「差不多同一处数据」，轨迹契约无声失效，"),a("a",{href:"/llm/pretrain-ckpt"},"检查点"),e("存的数据进度变成空引用。没有变更账，两周后复现某条曲线时，无人能答「当时喂的是哪个版本的数据」——这不是记忆问题，是设施没有提供查询接口。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"数字实例：一步 6 秒的训练，若每步因等数据多耗 50 毫秒，单看墙钟只慢不到 1%，几乎察觉不到；但跑一百万步累计就是约 14 小时纯空转，256 卡的作业折合三千五百多卡时。渐进退化靠肉眼与均值都抓不住，只能靠水位账的持续值报警。")],-1)),E[6]||(E[6]=a("p",null,"版本绑定的机制要特别钉死：作业启动时把流水线版本的哈希写进运行元数据，之后即使有人改了配比文件，在跑作业读到的仍是旧快照。实现上常把「配置读取」收敛为一次启动时的物化，而不是每 epoch 重读。",-1)),(B(),o(i,null,{default:t(()=>[A(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E5%8F%91%E7%8E%B0%E5%9D%8F%E6%89%B9%3A%20%E6%8D%9F%E5%A4%B1%E5%B0%96%E5%B3%B0%E6%88%96%E5%BC%82%E5%B8%B8%E6%A0%B7%E6%9C%AC%22%5D%20--%3E%20G%5B%22%E4%BB%8E%E5%BE%AE%E6%89%B9%E6%97%A5%E5%BF%97%E5%8F%96%E5%9B%9B%E5%85%83%E7%BB%84%22%5D%0A%20%20G%20--%3E%20T%5B%22%E6%B5%81%E6%B0%B4%E7%BA%BF%E7%89%88%E6%9C%AC%E5%8F%B7%20%2B%20%E7%A7%8D%E5%AD%90%E4%B8%8E%20epoch%22%5D%0A%20%20T%20--%3E%20M%5B%22%E5%90%AF%E5%8A%A8%E6%97%B6%E7%89%A9%E5%8C%96%E6%97%A7%E7%89%88%E6%9C%AC%E9%85%8D%E7%BD%AE%E5%BF%AB%E7%85%A7%22%5D%0A%20%20M%20--%3E%20R%5B%22%E6%8C%89%E6%B8%B8%E6%A0%87%E5%AE%9A%E4%BD%8D%E5%8C%BA%E9%97%B4%2C%20%E5%9B%BA%E5%AE%9A%20worker%20%E6%95%B0%E9%87%8D%E6%94%BE%22%5D%0A%20%20R%20--%3E%20H%7B%22token%20%E5%BA%8F%E5%88%97%E5%93%88%E5%B8%8C%E4%B8%80%E8%87%B4%3F%22%7D%0A%20%20H%20--%3E%7C%22%E6%98%AF%22%7C%20OK%5B%22%E5%A4%8D%E7%8E%B0%E6%88%90%E5%8A%9F%2C%20%E5%AE%9A%E4%BD%8D%E5%9D%8F%E6%95%B0%E6%8D%AE%E6%9D%A5%E6%BA%90%22%5D%0A%20%20H%20--%3E%7C%22%E5%90%A6%22%7C%20NG%5B%22%E6%9F%A5%E6%9C%AA%E9%92%89%E4%BD%8F%E7%9A%84%E9%9A%8F%E6%9C%BA%E9%A1%B9%E4%B8%8E%20RNG%20%E7%8A%B6%E6%80%81%22%5D%0A%20%20NG%20--%3E%20FX%5B%22%E9%92%89%E4%BD%8F%E5%90%8E%E4%BF%AE%E6%95%B0%E6%8D%AE%E6%8C%87%E7%BA%B9%2C%20%E9%87%8D%E5%85%A5%E9%BB%84%E9%87%91%E5%8C%BA%E9%97%B4%20CI%22%5D%0A%20%20FX%20--%3E%20R%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=l('<p><span class="marginnote">直觉类比：版本绑定就像餐厅给每桌客人下单时锁定了当日菜单——厨房后来换了新菜谱，只影响之后进门的客人，已下单的菜照旧谱做。训练作业同理：启动那一刻物化的配置快照，就是它「点过的菜」，后续改配比不动在跑的 run。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课管的是把 token 按时、按账、可复现地送到 GPU，不管喂什么：语料怎么选、去重与污染怎么清、配比怎么定，属于数据课程与配比各课的口径；也不管数据并行下的分片到 rank 的拓扑细节。回放能力有边界：涉及随机丢弃（如随机过滤、dropout 式增强）的流水线，确定性要连 RNG 状态一起钉，否则黄金区间比对只能在关掉随机项的配置下做。流式数据源若上游本身变动（对方删了文件），版本号也救不回，只能靠本地缓存层兜底。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>流水线运营三账：吞吐（水位与阶段 P99）、确定性（数据指纹）、变更（版本号绑定）。</li><li>报警看队列水位持续值，不看 CPU 利用率；预取深度按 P99 设。</li><li>坏批回放最小四元组：版本、种子与 epoch、游标、worker 数；进 CI 的黄金区间比对。</li><li>作业启动时物化配置快照，在跑作业不受后续变更影响。</li><li>出处：据 WebDataset、Mosaic Streaming 文档与 BLOOM 训练纪事（Le Scao et al., 2022）整理；阶段划分见<a href="/llm/dataloader-pipeline">数据加载流水线</a>。</li></ul>',5))])}const P=n(d,[["render",D]]);export{k as __pageData,P as default};
